SET client_encoding = 'UTF8';

SET standard_conforming_strings = on;

LOCK TABLE public.ingredients IN ACCESS EXCLUSIVE MODE;

DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.ingredients) THEN RAISE EXCEPTION 'ingredients is not empty'; END IF; END $$;

LOCK TABLE public.recipes IN ACCESS EXCLUSIVE MODE;

DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.recipes) THEN RAISE EXCEPTION 'recipes is not empty'; END IF; END $$;

LOCK TABLE public.recipe_ingredients IN ACCESS EXCLUSIVE MODE;

DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.recipe_ingredients) THEN RAISE EXCEPTION 'recipe_ingredients is not empty'; END IF; END $$;

LOCK TABLE public.recipe_steps IN ACCESS EXCLUSIVE MODE;

DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.recipe_steps) THEN RAISE EXCEPTION 'recipe_steps is not empty'; END IF; END $$;

LOCK TABLE public.recipe_scraps IN ACCESS EXCLUSIVE MODE;

DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.recipe_scraps) THEN RAISE EXCEPTION 'recipe_scraps is not empty'; END IF; END $$;






DO $$ BEGIN IF (SELECT count(*) FROM public.ingredients) <> 148 THEN RAISE EXCEPTION 'ingredients count mismatch'; END IF; END $$;

DO $$ BEGIN IF (SELECT count(*) FROM public.recipes) <> 21491 THEN RAISE EXCEPTION 'recipes count mismatch'; END IF; END $$;

DO $$ BEGIN IF (SELECT count(*) FROM public.recipe_ingredients) <> 179603 THEN RAISE EXCEPTION 'recipe_ingredients count mismatch'; END IF; END $$;

DO $$ BEGIN IF (SELECT count(*) FROM public.recipe_steps) <> 166436 THEN RAISE EXCEPTION 'recipe_steps count mismatch'; END IF; END $$;

DO $$ BEGIN IF (SELECT count(*) FROM public.recipe_scraps) <> 0 THEN RAISE EXCEPTION 'recipe_scraps count mismatch'; END IF; END $$;
